import React, { useState } from "react";
import { storiesAPI } from "../services/api";

const StoryForm = ({ onSuccess, employees = [] }) => {
  const [formData, setFormData] = useState({ 
    image: "", 
    caption: "",
    authorId: "admin", // Default to admin
  });
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const payload = {
        image: formData.image,
        caption: formData.caption,
        authorId: formData.authorId === "admin" ? null : formData.authorId,
        onModel: formData.authorId === "admin" ? "User" : "Employee"
      };

      await storiesAPI.create(payload);
      setFormData({ image: "", caption: "", authorId: "admin" });
      setMessage("Story created successfully!");
      setTimeout(() => setMessage(""), 3000);
      onSuccess();
    } catch (error) {
      setMessage(error.response?.data?.message || "Error creating story");
    } finally {
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="form-card">
      <h3>Create New Story</h3>

      <div className="form-group">
        <label>Post As:</label>
        <select 
          name="authorId" 
          value={formData.authorId} 
          onChange={handleChange}
          style={{ width: '100%', padding: '10px', marginTop: '5px', borderRadius: '8px', border: '1px solid #ddd' }}
        >
          <option value="admin">Admin (Self)</option>
          {employees.map(emp => (
            <option key={emp._id} value={emp._id}>{emp.name}</option>
          ))}
        </select>
      </div>

      <div className="form-group" style={{ marginTop: '15px' }}>
        <input
          type="text"
          name="image"
          placeholder="Image URL"
          value={formData.image}
          onChange={handleChange}
          required
          style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ddd' }}
        />
      </div>

      <div className="form-group" style={{ marginTop: '15px' }}>
        <textarea
          name="caption"
          placeholder="Story caption (optional)"
          value={formData.caption}
          onChange={handleChange}
          style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #ddd', minHeight: '80px' }}
        />
      </div>

      {message && <p className="message" style={{ color: '#ff6ce7', fontWeight: 'bold' }}>{message}</p>}

      <button 
        type="submit" 
        disabled={loading}
        style={{ marginTop: '15px', width: '100%', padding: '12px', background: '#ff6ce7', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}
      >
        {loading ? "Creating..." : "Post Story"}
      </button>
    </form>
  );
};

export default StoryForm;
